  "The frontend and backend are maintained as separate repositories, making the control plane easier to inspect, adapt, and self-host.": "فرانت‌اند و بک‌اند در مخزن‌های جداگانه نگهداری می‌شوند تا راحت‌تر بررسی و سفارشی‌سازی‌شان کنید و بتوانید پنل را روی زیرساخت خودتان اجرا کنید.",
  "Start with the control plane, then make the infrastructure as custom as your workload demands.": "از پنل مدیریت شروع کنید و زیرساخت را متناسب با نیاز اپلیکیشن‌تان تنظیم کنید.",
  "Choose the resources that fit your workload.": "منابعی را انتخاب کنید که با نیاز اپلیکیشن‌تان هماهنگ باشد.",
  "PaaSDeployer is a self-hosted application deployment platform built around one idea: make the path from configured workload to running service easier to understand, operate and automate.": "PaaSDeployer یک پلتفرم خودمیزبان برای دیپلوی اپلیکیشن‌هاست؛ طوری طراحی شده که راه‌اندازی، مدیریت و خودکارسازی سرویس‌ها راحت‌تر باشد.",
  "Compare application and data-service resources and choose the plan that fits your workload. Plans are billed by the hour — start small, scale up, and pay only while a service is running.": "منابع موردنیاز اپلیکیشن و دیتابیس را مقایسه کنید و پلنی را انتخاب کنید که به کارتان می‌آید. هزینه به‌صورت ساعتی حساب می‌شود؛ با منابع کمتر شروع کنید، در صورت نیاز آن‌ها را افزایش دهید و فقط وقتی سرویس در حال اجراست هزینه بپردازید.",
  "PaaSDeployer is a self-hosted platform as a service for deploying React, Node.js, Django and Flask applications with Docker, PostgreSQL, Redis, networking, persistent storage, logs and service management in one control plane.": "PaaSDeployer یک پلتفرم PaaS خودمیزبان برای دیپلوی اپلیکیشن‌های React، Node.js، Django و Flask است. Docker، PostgreSQL، Redis، شبکه، استوریج، لاگ‌ها و مدیریت سرویس‌ها را هم از یک پنل در اختیارتان می‌گذارد.",
  "Build, ship and operate modern applications without assembling infrastructure by hand. One focused control plane for code, services, networks, storage and deployments.": "اپلیکیشن‌های مدرن را بدون دردسر آماده‌سازی دستی زیرساخت، بیلد، منتشر و مدیریت کنید. کد، سرویس‌ها، شبکه، استوریج و دیپلوی‌ها همه در یک پنل مدیریت در دسترس‌اند.",
  "PaaSDeployer keeps the operational surface area small: one place to create services, ship releases, read logs and manage the runtime boundary around your workloads.": "PaaSDeployer مدیریت عملیات را ساده و متمرکز می‌کند: از ساخت سرویس و انتشار نسخه گرفته تا دیدن لاگ‌ها و مدیریت Runtime، همه‌چیز در یک جاست.",
  "PaaSDeployer is designed for modern web workloads, including React frontends, Node.js services, Django and Flask applications, databases, caches, and Docker-based workloads.": "PaaSDeployer برای اپلیکیشن‌های مدرن وب ساخته شده؛ از فرانت‌اند React و سرویس‌های Node.js گرفته تا برنامه‌های Django و Flask، دیتابیس، کش و سرویس‌های مبتنی بر Docker.",
  "React and static web workloads": "اپلیکیشن‌های React و وب‌سایت‌های استاتیک",
  "Connect scoped automation clients and AI agents to the PaaSDeployer control plane with audited, idempotent operations.": "کلاینت‌های خودکارسازی و ایجنت‌های هوش مصنوعی را با دسترسی‌های محدود به پنل مدیریت PaaSDeployer وصل کنید؛ درخواست‌ها ثبت و قابل‌پیگیری‌اند و اجرای دوباره‌شان اثر تکراری ایجاد نمی‌کند.",
  "Connect scoped automation clients and AI agents to the PaaSDeployer control plane. Agents are account-level resources and are not tied to this service.": "کلاینت‌های خودکارسازی و ایجنت‌های هوش مصنوعی را با دسترسی محدود به پنل مدیریت PaaSDeployer وصل کنید. ایجنت‌ها به حساب شما تعلق دارند و به سرویس خاصی وابسته نیستند.",
  "Manage scoped machine access to your PaaSDeployer control plane for automation clients and AI agents.": "دسترسی محدود کلاینت‌های خودکارسازی و ایجنت‌های هوش مصنوعی به پنل مدیریت PaaSDeployer را مدیریت کنید.",
  "Create an Agent, grant only the scopes it needs, then issue a short-lived credential for your automation client.": "یک ایجنت بسازید، فقط دسترسی‌های موردنیازش را به آن بدهید و بعد برای کلاینت خودکارسازی‌تان یک توکن کوتاه‌مدت صادر کنید.",
