  "Explore docs": "مشاهدهٔ مستندات",
  "Built for teams that want the platform under their control.": "برای تیم‌هایی ساخته شده که می‌خواهند کنترل پلتفرم را خودشان در دست داشته باشند.",
  "Start with the software you already know.": "با همان نرم‌افزارهایی شروع کنید که می‌شناسید.",
  "Pick a proven self-hosted app and let PaaSDeployer handle the supporting services, runtime setup and operational baseline.": "یک اپلیکیشن خودمیزبانِ مطمئن انتخاب کنید و بگذارید PaaSDeployer سرویس‌های وابسته، محیط اجرا و تنظیمات اولیهٔ آن را آماده کند.",
  "Browse all apps": "دیدن همهٔ اپلیکیشن‌ها",
  "Code moves forward. The platform does the heavy lifting.": "کد را جلو ببرید؛ کارهای اجرایی را به پلتفرم بسپارید.",
  "A clear path from repository to running service.": "از مخزن کد تا سرویسِ آماده، همه‌چیز روشن و قابل‌پیگیری است.",
  "pipeline · build · release": "پایپ‌لاین · بیلد · ریلیز",
  "Bring your stack": "از استک فناوری خودتان استفاده کنید.",
  "The boring parts should stay boring.": "کارهای تکراری باید ساده و بی‌دردسر پیش بروند.",
  "Built in public": "توسعهٔ شفاف و متن‌باز",
  "Inspect it. Adapt it. Run it yourself.": "اجزای آن را بررسی کنید، مطابق نیازتان تغییر دهید و خودتان اجرا کنید.",
  "No services yet.": "هنوز سرویسی نساخته‌اید.",
  "Open Services": "مشاهدهٔ سرویس‌ها",
  "PaaSDeployer is intentionally broad enough to support the application layer and focused enough to keep the operations experience understandable.": "PaaSDeployer از فناوری‌های مختلف اپلیکیشن پشتیبانی می‌کند، اما محیط مدیریت آن را ساده و قابل‌فهم نگه می‌دارد.",
  "Everything you need to run day-to-day operations lives in one place — so you spend less time wiring tools and more time shipping product.": "همهٔ ابزارهای لازم برای کارهای روزمره یک‌جا جمع شده‌اند؛ وقت کمتری صرف سرهم‌کردن ابزارها می‌کنید و بیشتر روی انتشار محصول تمرکز می‌کنید.",
  "Can resources be changed later?": "می‌توانم بعداً منابع سرویس را تغییر بدهم؟",
  "Can PaaSDeployer be automated?": "می‌توانم کارهای PaaSDeployer را خودکار کنم؟",
  "Application runtime": "Runtime اپلیکیشن",
  "Point a service at your repository and let the platform own the rest of the path.": "مخزن کدتان را به سرویس وصل کنید؛ ادامهٔ کار را به پلتفرم بسپارید.",
  "Promote a release into the environment with clear status, logs and health signals.": "نسخهٔ جدید را با وضعیت، لاگ‌ها و شاخص‌های سلامت مشخص در محیط اجرا منتشر کنید.",
  "Keep networking, storage and resource controls close to the service itself.": "تنظیمات شبکه، استوریج و منابع را همان‌جا، کنار خود سرویس، مدیریت کنید.",
  "Track releases, build state, logs and rollout health.": "وضعیت بیلد، نسخه‌های منتشرشده، لاگ‌ها و سلامت انتشار را دنبال کنید.",
  "Keep CPU, memory and storage close to the service definition.": "تنظیمات CPU، حافظه و استوریج را کنار مشخصات سرویس ببینید و مدیریت کنید.",
  "Use isolated containers and clear service boundaries as the execution model.": "سرویس‌ها در کانتینرهای جداگانه اجرا می‌شوند و هرکدام مرز مشخصی دارند.",
  "Managed WordPress with database setup, WP-CLI and runtime controls.": "WordPress مدیریت‌شده با دیتابیس آماده، WP-CLI و تنظیمات Runtime.",
  "Team chat packaged with its supporting database stack.": "گفتگوی تیمی به‌همراه دیتابیس و سرویس‌های موردنیازش.",
  "Compare compute, memory and storage plans directly from the homepage. Open the full Plans workspace for all platforms, filters, and service creation.": "پلن‌های پردازنده، حافظه و استوریج را از صفحهٔ اصلی مقایسه کنید. برای دیدن همهٔ پلتفرم‌ها، فیلترها و ساخت سرویس به بخش پلن‌ها بروید.",
  "No plans are available right now.": "فعلاً پلنی برای نمایش وجود ندارد.",
  "From commit to running service": "از Commit تا سرویسِ در حال اجرا",
  "Infrastructure should feel like a product.": "کار با زیرساخت هم باید به سادگی کار با یک محصول خوب باشد.",
  "Operator workspace": "محیط کار اپراتور",
  "Runtime layer": "لایهٔ اجرا",
  "Why it exists": "چرا PaaSDeployer را ساختیم",
  "A control plane built around the work that actually matters.": "یک پنل مدیریت برای کارهایی که واقعاً اهمیت دارند.",
  "Instead of treating deployment, services and infrastructure as separate worlds, PaaSDeployer keeps them in one operator experience.": "PaaSDeployer دیپلوی، سرویس‌ها و زیرساخت را جدا از هم مدیریت نمی‌کند؛ همه‌چیز در یک محیط یکپارچه در دسترس است.",
  "Practical by default": "از همان ابتدا کاربردی",
  "The interface focuses on the actions operators repeat instead of exposing infrastructure ceremony for its own sake.": "رابط کاربری روی کارهایی تمرکز دارد که اپراتورها هر روز انجام می‌دهند؛ نه نمایش پیچیدگی‌ها و تشریفات غیرضروری زیرساخت.",
  "Clear boundaries": "مرزبندی روشن",
  "The control plane is split into a Django backend and React frontend that can be inspected, changed and self-hosted.": "پنل مدیریت از بک‌اند Django و فرانت‌اند React تشکیل شده؛ می‌توانید هر دو را بررسی کنید، تغییر دهید و روی زیرساخت خودتان میزبانی کنید.",
  "What the platform connects": "اجزایی که پلتفرم به هم وصل می‌کند",
  "Operate": "مدیریت و پایش",
  "Start, stop, rebuild, inspect and monitor services from the workspace.": "از همین محیط کاری سرویس‌ها را روشن و خاموش کنید، دوباره بسازید، بررسی و پایش کنید.",
  "Treat networks, volumes and supporting infrastructure as first-class resources.": "شبکه‌ها، Volumeها و سرویس‌های وابسته را هم مثل خود سرویس‌ها به‌عنوان منابع مستقل مدیریت کنید.",
  "Start with software, not infrastructure assembly.": "به‌جای درگیرشدن با آماده‌سازی زیرساخت، مستقیم از خود اپلیکیشن شروع کنید.",
  "Popular self-hosted applications can arrive with their supporting services, storage and configuration already described by the catalog.": "اپلیکیشن‌های محبوب خودمیزبان از قبل با سرویس‌های وابسته، استوریج و تنظیمات لازم در کاتالوگ تعریف شده‌اند.",
